// تحضير الـ prompt للرسائل النصية
const data = $input.first().json;
const text = data.body_text || data.transcribed_text || '';

const systemPrompt = `أنت مساعد محاسبي متخصص لفندق مصري اسمه هوستل الأهرامات.

مهمتك: تحليل رسالة واتساب من موظف الفندق وإخراج JSON منظّم فقط بدون أي نص إضافي.

أنواع العمليات الممكنة:
1. GUEST_CHECKIN — دخول نزيل
   مؤشرات: دخول، نزيل، تسجيل، check in، غرفة، ليلة
2. CAFE_SHIFT — تقفيل وردية الكافيه/المطعم
   مؤشرات: تقفيل، كافيه، مطعم، وردية، مبيعات، إجمالي
3. EXPENSE_BILL — فاتورة مشتريات/مصروف
   مؤشرات: فاتورة، مصروف، شراء، مورد، صيانة

قواعد صارمة:
- إذا لم تستطع تحديد النوع، اجعل transaction_type = UNKNOWN
- المبالغ دائماً بالجنيه المصري
- إذا ذُكرت الضرائب، اجعل tax_included = true
- إذا لم يُذكر طريقة الدفع، اجعل payment_method = unknown
- أخرج JSON فقط بهذا الشكل بالضبط:
{
  "transaction_type": "GUEST_CHECKIN | CAFE_SHIFT | EXPENSE_BILL | UNKNOWN",
  "amount": 0.00,
  "payment_method": "cash | card | transfer | unknown",
  "details": {
    "guest_name": "",
    "room_number": "",
    "nights": 0,
    "vendor_name": "",
    "tax_included": true,
    "shift": "morning | evening | night",
    "notes": ""
  }
}`;

const payload = {
  contents: [
    {
      parts: [
        { text: systemPrompt },
        { text: `حلّل هذه الرسالة:\n\n${text}` }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.1,
    maxOutputTokens: 512,
    responseMimeType: "application/json"
  }
};

return [{ json: { gemini_payload: payload, original: data, is_image: false } }];

// تحضير الـ prompt لصور الفواتير (Vision)
const data = $input.first().json;
const imageBase64 = $input.first().binary?.data
  ? Buffer.from($input.first().binary.data).toString('base64')
  : '';

const systemPrompt = `أنت نظام OCR + تحليل محاسبي. استخرج بيانات الفاتورة من الصورة.
اجعل transaction_type = EXPENSE_BILL دائماً لصور الفواتير.
أخرج JSON فقط بهذا الشكل:
{
  "transaction_type": "EXPENSE_BILL",
  "amount": 0.00,
  "payment_method": "unknown",
  "details": {
    "vendor_name": "",
    "tax_included": true,
    "notes": ""
  }
}`;

const payload = {
  contents: [
    {
      parts: [
        { text: systemPrompt },
        {
          inline_data: {
            mime_type: "image/jpeg",
            data: imageBase64
          }
        },
        { text: "استخرج بيانات هذه الفاتورة وأخرج JSON:" }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.1,
    maxOutputTokens: 512,
    responseMimeType: "application/json"
  }
};

return [{ json: { gemini_payload: payload, original: data, is_image: true } }];

// استخراج JSON من استجابة Gemini والتحقق منه
const raw = $input.first().json;
const originalData = $('Receive from Webhook').item?.json || {};

let parsed;
try {
  // Gemini يُرجع النص داخل candidates[0].content.parts[0].text
  const rawText = raw?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  // تنظيف أي markdown كودي
  const cleaned = rawText
    .replace(/```json\n?/gi, '')
    .replace(/```\n?/gi, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{ json: {
    transaction_type: 'UNKNOWN',
    parse_error: true,
    error_detail: e.message,
    raw_response: raw,
    from_number: originalData.from_number,
    contact_name: originalData.contact_name,
    is_valid: false
  }}];
}

// التحقق من الحقول الأساسية
const isValid =
  parsed.transaction_type &&
  parsed.transaction_type !== 'UNKNOWN' &&
  parsed.amount > 0;

return [{ json: {
  ...parsed,
  from_number: originalData.from_number,
  contact_name: originalData.contact_name,
  is_valid: isValid,
  parsed_at: new Date().toISOString()
}}];

